import {
  test as anonymousTest,
  expect,
} from "../helpers/system-control-browser";
import { test as premiumTest } from "../helpers/theme-browser";
import type { Page, TestInfo } from "@playwright/test";

async function capture(
  page: Page,
  info: TestInfo,
  route: string,
  appearance: string,
  mode: string,
) {
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.setViewportSize({
    width: info.project.name === "desktop" ? 1440 : 320,
    height: 1000,
  });
  await page.addInitScript(
    ({ appearance, mode }) => {
      localStorage.setItem("mailloop-appearance", appearance);
      localStorage.setItem("mailloop-theme", mode);
    },
    { appearance, mode },
  );
  await page.goto(`${route}?country=US`);
  await expect(page.locator("html")).toHaveAttribute("data-theme", mode);
  await expect(page.locator("html")).toHaveAttribute(
    "data-appearance",
    appearance,
  );
  await expect(page.locator("main")).toBeVisible();
  await page.evaluate(async () => {
    await document.fonts.ready;
    await Promise.all(
      [...document.images].map((img) => img.decode().catch(() => {})),
    );
  });
  if (route === "/" || route === "/pricing")
    await expect(page.locator("[data-localized-price]").first()).toContainText(
      /\d/,
    );
  expect(
    await page.evaluate(() => document.documentElement.scrollWidth),
  ).toBeLessThanOrEqual(page.viewportSize()!.width);
  await expect(page).toHaveScreenshot(
    `${route === "/" ? "landing" : route.slice(1)}-${appearance}-${mode}.png`,
    {
      fullPage: true,
      animations: "disabled",
      caret: "initial",
      stylePath: "tests/helpers/screenshot.css",
      maxDiffPixelRatio: 0.005,
    },
  );
}

for (const mode of ["light", "dark"]) {
  anonymousTest(`landing visual: ${mode}`, async ({ page }, info) => {
    await capture(page, info, "/", "purple", mode);
  });
}

for (const route of ["/pricing", "/privacy", "/terms"]) {
  for (const appearance of ["purple", "vercel"]) {
    for (const mode of ["light", "dark"]) {
      premiumTest(
        `public visual: ${route} ${appearance} ${mode}`,
        async ({ page }, info) => {
          await capture(page, info, route, appearance, mode);
        },
      );
    }
  }
}
